    "explanation": "21-hidroksilaz eksikliği kortizol ve sıklıkla aldosteron sentezini azaltırken prekürsörlerin androjen yoluna kaymasına neden olur. Yükselen 17-hidroksiprogesteron en tipik laboratuvar bulgusudur; kortizol ve aldosteron yükselmez, metanefrin feokromositoma değerlendirmesiyle ilişkilidir. 21-hidroksilaz eksikliğinde 17-hidroksiprogesteron kortizol yolunda ilerleyemez ve birikir; bu nedenle yenidoğan taraması ve tanısal değerlendirmede temel belirteçtir. 21-hidroksilaz basamağı bloke olduğunda biriken temel prekürsördür; taramada en önemli belirteçtir. TUS açısından ayırıcı nokta: 21-hidroksilaz eksikliği = yüksek 17-hidroksiprogesteron; 11β-hidroksilaz eksikliği ise hipertansiyon yapan 11-deoksikortikosteron artışıyla ayrılır.",
    "answerAnalysisIntro": "Bu soru laboratuvar belirtecinin neyi ölçtüğünü ve hangi durumda ayırıcı değer taşıdığını yorumlamayı hedefler.",
