    "explanation": "Kavernöz sinüste n. Abducens, internal karotis arterle yakın komşulukta sinüs içinden geçer. N. Oculomotorius, n. Trochlearis, n. Ophthalmicus ve n. Maxillaris daha çok lateral duvarda seyreder. Bu anatomik fark, kavernöz sinüs lezyonlarında abdusens paralizisinin sık ve erken görülmesini açıklar. Abducens kavernöz sinüs lümeni içinde internal karotis artere komşu seyreder; III, IV, V1 ve V2 ise lateral duvarda yer alır. Doğru. Abducens internal karotis arterle birlikte kavernöz sinüs içinde seyreder. TUS açısından ayırıcı nokta: Kavernöz sinüs: lateral duvar III, IV, V1, V2; lümen içi ise internal karotis arter ve VI. Sinirdir.",
